import html


def html_page(address):
    esc = html.escape(address)
    return f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>DeckyShare</title><style>
*{{box-sizing:border-box}}:root{{--bg:#07111f;--line:rgba(112,177,255,.20);--blue:#69c6ff;--text:#f4f8ff;--muted:#9eb2c9;--good:#7ef29a}}html{{color-scheme:dark}}body{{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:radial-gradient(circle at 50% -10%,#14365d 0,#08182b 34%,#050d18 72%);color:var(--text);margin:0;min-height:100vh;padding:24px}}.wrap{{width:100%;max-width:960px;margin:auto}}.hero{{padding:20px 4px 10px}}.brand{{display:flex;align-items:center;gap:11px}}.logo{{width:42px;height:42px;flex:0 0 42px;border-radius:13px;display:grid;place-items:center;background:linear-gradient(145deg,rgba(73,160,255,.28),rgba(59,99,185,.14));border:1px solid rgba(118,187,255,.28);font-size:23px}}h1{{margin:0;font-size:28px;letter-spacing:-.3px}}.version{{font-size:11px;padding:3px 7px;border-radius:999px;background:rgba(84,165,255,.14);border:1px solid rgba(111,185,255,.22);color:#9fd4ff;vertical-align:middle}}.tagline{{margin:5px 0 0;color:var(--muted);font-size:14px}}.ready{{display:inline-flex;align-items:center;gap:6px;margin-top:12px;padding:6px 9px;border-radius:999px;background:rgba(64,212,121,.10);color:var(--good);font-size:12px;font-weight:700}}.grid{{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px;margin-top:12px;align-items:start}}.card{{min-width:0;background:linear-gradient(180deg,rgba(20,43,73,.94),rgba(10,25,43,.96));border:1px solid var(--line);border-radius:18px;padding:18px;margin:16px 0;box-shadow:0 12px 32px rgba(0,0,0,.20)}}.grid .card{{margin:0}}h2{{margin:0 0 5px;font-size:18px}}.sub{{margin:0 0 14px;color:var(--muted);font-size:13px;line-height:1.45}}button,.btn,input[type=file]{{font:inherit;font-size:15px}}button,.btn{{display:inline-flex;align-items:center;justify-content:center;min-height:44px;background:linear-gradient(180deg,rgba(52,102,164,.92),rgba(28,59,99,.94));color:#fff;border:1px solid rgba(110,180,255,.30);border-radius:11px;padding:11px 14px;text-decoration:none;font-weight:750;cursor:pointer;text-align:center}}button:disabled{{opacity:.48;cursor:not-allowed}}input[type=file]{{width:100%;max-width:100%;padding:18px 14px;border-radius:14px;border:1px dashed rgba(121,190,255,.42);background:rgba(30,67,111,.32);color:#dbeeff;min-height:72px}}.muted{{color:var(--muted)}}.selected-box{{min-height:72px;padding:13px;border:1px solid rgba(116,183,255,.15);background:rgba(63,126,191,.08);border-radius:13px;display:flex;align-items:center;overflow-wrap:anywhere}}.bar{{height:9px;background:rgba(255,255,255,.10);border-radius:999px;overflow:hidden;margin-top:8px}}.fill{{height:100%;background:linear-gradient(90deg,#58b8f3,#80d4ff);width:0}}.row{{margin:10px 0}}.controls{{display:flex;gap:8px;flex-wrap:wrap}}.controls button{{flex:1;min-width:120px}}.queue-item{{padding:9px 0;border-bottom:1px solid rgba(255,255,255,.06);overflow-wrap:anywhere}}.queue-item:last-child{{border-bottom:0}}.connection{{display:flex;align-items:center;justify-content:space-between;gap:10px}}code{{word-break:break-all;color:#84ceff}}.support{{text-align:center}}
@media(max-width:700px){{body{{padding:max(10px,env(safe-area-inset-top)) max(10px,env(safe-area-inset-right)) max(18px,env(safe-area-inset-bottom)) max(10px,env(safe-area-inset-left));background:radial-gradient(circle at 50% -5%,#14365d 0,#08182b 30%,#050d18 68%);-webkit-text-size-adjust:100%}}.wrap{{max-width:520px}}.hero{{padding:8px 3px 10px}}.brand{{align-items:flex-start;gap:10px}}.logo{{width:38px;height:38px;flex-basis:38px;border-radius:11px;font-size:21px}}h1{{font-size:23px;line-height:1.15}}.version{{font-size:9px;padding:2px 5px;white-space:nowrap}}.tagline{{font-size:12px;line-height:1.4;margin-top:4px}}.ready{{margin-top:10px;font-size:11px}}.grid{{grid-template-columns:1fr;gap:10px;margin-top:4px}}.card,.grid .card{{margin:10px 0 0;padding:15px;border-radius:15px;box-shadow:0 8px 22px rgba(0,0,0,.18)}}.grid .card{{margin:0}}h2{{font-size:17px}}.sub{{font-size:12px;margin-bottom:12px}}button,.btn,input[type=file]{{font-size:16px}}button,.btn{{width:100%;min-height:48px;padding:12px;border-radius:12px}}input[type=file]{{min-height:64px;padding:14px 12px}}.selected-box{{min-height:64px}}.download-row{{margin-bottom:4px}}.controls{{display:grid;grid-template-columns:1fr 1fr;gap:8px}}.controls button{{min-width:0}}.controls #upload{{grid-column:1/-1}}.connection{{align-items:flex-start;flex-direction:column}}.connection>div{{max-width:100%}}.support .btn{{width:100%}}}}
@media(min-width:701px){{.grid .card{{min-height:326px}}.support .btn{{min-width:180px}}}}
</style></head><body><div class="wrap">
<div class="hero"><div class="brand"><div class="logo">↔</div><div><h1>DeckyShare <span class="version">v1.1-dev</span></h1><div class="tagline">Fast local file sharing for Steam Deck — no app required on phone or PC.</div></div></div><div class="ready">● Connected on local network</div></div>
<div class="grid">
<div class="card"><h2>Receive from Deck</h2><p class="sub">Choose a file in the Decky panel, then download it here.</p><div class="selected-box"><div id="selected">Loading…</div></div><div class="row download-row"><a id="download" class="btn" style="display:none">Download selected file</a></div><div id="awake" class="muted" style="font-size:12px;line-height:1.4">Screen-awake protection is checked when a transfer starts.</div></div>
<div class="card"><h2>Send to Deck</h2><p class="sub">Pick one or more files. DeckyShare queues them automatically.</p><input id="file" type="file" multiple><div class="row controls"><button id="upload">Send files</button><button id="pause" disabled>Pause</button><button id="cancel" disabled>Cancel</button></div><div id="uptext" class="muted"></div><div id="diag" class="muted" style="font-size:11px;margin-top:5px"></div><div class="bar"><div id="upbar" class="fill"></div></div><div id="queue" class="muted row"></div></div>
</div>
<div class="card"><h2>Live transfers</h2><p class="sub">Current progress, speed and ETA.</p><div id="transfers" class="muted">No active transfer</div></div>
<div class="card connection"><div><div style="font-size:12px;font-weight:750;margin-bottom:3px">Connected to Steam Deck</div><code>{esc}</code></div><div style="font-size:12px;color:var(--good);font-weight:700">● Ready</div></div>
<div class="card support"><h2>☕ Support DeckyShare</h2><p class="sub">Free and open source. If it helps you, you can support future development.</p><a class="btn" href="https://buymeacoffee.com/Gillrv" target="_blank" rel="noopener">Buy me a coffee</a></div></div>
<script>
async function api(path,opt){{const r=await fetch(path,opt);if(!r.ok)throw new Error(await r.text());return r;}}
function fmt(n){{if(n>=1073741824)return(n/1073741824).toFixed(1)+' GB';if(n>=1048576)return(n/1048576).toFixed(1)+' MB';if(n>=1024)return(n/1024).toFixed(1)+' KB';return Math.round(n||0)+' B';}}
async function refresh(){{try{{const s=await(await api('/api/status')).json(),el=document.getElementById('selected'),a=document.getElementById('download');if(s.selected){{el.innerHTML='<div><b>'+escapeHtml(s.selected.name)+'</b><div class="muted" style="font-size:12px;margin-top:4px">'+escapeHtml(s.selected.size_human)+'</div></div>';a.style.display='inline-block';a.href='/download';}}else{{el.textContent='Choose a file in the Decky panel first.';a.style.display='none';}}const box=document.getElementById('transfers');if(!s.transfers.length)box.innerHTML='<span class="muted">No active transfer</span>';else box.innerHTML=s.transfers.map(x=>`<div class="row"><b>${{x.direction==='upload'?'To Deck':'From Deck'}}:</b> ${{escapeHtml(x.name)}}<br><span class="muted">${{Number(x.percent||0).toFixed(1)}}% • ${{fmt(x.speed)}}/s ${{x.eta?('• ETA '+Math.ceil(x.eta)+'s'):''}}</span><div class="bar"><div class="fill" style="width:${{Math.min(100,x.percent||0)}}%"></div></div></div>`).join('');}}catch(e){{}}}}
function escapeHtml(v){{return String(v||'').replace(/[&<>\"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}}[c]));}}
let crcTable=null;function crc32(buf){{if(!crcTable){{crcTable=new Uint32Array(256);for(let n=0;n<256;n++){{let c=n;for(let k=0;k<8;k++)c=(c&1)?(0xedb88320^(c>>>1)):(c>>>1);crcTable[n]=c>>>0;}}}}let c=0xffffffff;for(let i=0;i<buf.length;i++)c=crcTable[(c^buf[i])&255]^(c>>>8);return((c^0xffffffff)>>>0).toString(16).padStart(8,'0');}}
let crcWorker=null,crcJob=0,crcPending=new Map();
function getCrcWorker(){{if(crcWorker)return crcWorker;try{{const source=`self.onmessage=e=>{{const buffer=e.data.buffer,b=new Uint8Array(buffer),t=new Uint32Array(256);for(let n=0;n<256;n++){{let c=n;for(let k=0;k<8;k++)c=(c&1)?(0xedb88320^(c>>>1)):(c>>>1);t[n]=c>>>0;}}let c=0xffffffff;for(let i=0;i<b.length;i++)c=t[(c^b[i])&255]^(c>>>8);self.postMessage({{id:e.data.id,sum:((c^0xffffffff)>>>0).toString(16).padStart(8,'0'),buffer}},[buffer]);}}`;crcWorker=new Worker(URL.createObjectURL(new Blob([source],{{type:'text/javascript'}})));crcWorker.onmessage=e=>{{const p=crcPending.get(e.data.id);if(p){{crcPending.delete(e.data.id);p.resolve({{sum:e.data.sum,buffer:e.data.buffer}});}}}};crcWorker.onerror=()=>{{for(const p of crcPending.values())p.reject(new Error('CRC worker failed'));crcPending.clear();try{{crcWorker.terminate();}}catch(e){{}}crcWorker=null;}};return crcWorker;}}catch(e){{return null;}}}}
async function crc32Async(buffer){{const worker=getCrcWorker();if(!worker)return{{sum:crc32(new Uint8Array(buffer)),buffer}};const id=++crcJob;return new Promise((resolve,reject)=>{{crcPending.set(id,{{resolve,reject}});try{{worker.postMessage({{id,buffer}},[buffer]);}}catch(e){{crcPending.delete(id);reject(e);}}}});}}
async function prepareUploadChunk(f,off,chunk){{const end=Math.min(f.size,off+chunk),readStart=performance.now(),buffer=await f.slice(off,end).arrayBuffer(),readMs=performance.now()-readStart,crcStart=performance.now(),checked=await crc32Async(buffer),crcMs=performance.now()-crcStart;return{{off,end,blob:checked.buffer,sum:checked.sum,readMs,crcMs}};}}
function showUploadDiagnostic(current,uploadMs,serverMs){{const el=document.getElementById('diag');if(el)el.textContent=`Chunk diagnostic • Read ${{Math.round(current.readMs)}}ms • CRC ${{Math.round(current.crcMs)}}ms • Upload ${{Math.round(uploadMs)}}ms • Server ${{Math.round(serverMs||0)}}ms`;}}
let wakeLock=null;
function setAwakeText(text){{const el=document.getElementById('awake');if(el)el.textContent=text;}}
async function requestTransferWakeLock(){{
  if(!('wakeLock' in navigator)||!navigator.wakeLock||typeof navigator.wakeLock.request!=='function'){{
    setAwakeText('Keep this screen on during large transfers. This browser does not expose screen-awake protection here.');
    return false;
  }}
  try{{
    if(wakeLock&&!wakeLock.released)return true;
    wakeLock=await navigator.wakeLock.request('screen');
    setAwakeText('✓ Screen-awake protection active during transfer');
    wakeLock.addEventListener('release',()=>{{setAwakeText('Screen-awake protection released. Keep this page visible during large transfers.');}});
    return true;
  }}catch(e){{
    setAwakeText('Keep this screen on during large transfers. Screen-awake protection was blocked by the browser.');
    return false;
  }}
}}
async function releaseTransferWakeLock(){{
  try{{if(wakeLock&&!wakeLock.released)await wakeLock.release();}}catch(e){{}}
  wakeLock=null;
}}
document.addEventListener('visibilitychange',()=>{{
  if(document.visibilityState==='visible'&&uploadControl.running)requestTransferWakeLock();
}});

let uploadControl={{running:false,paused:false,cancelled:false,controller:null}},queueState=[];
function renderQueue(){{const q=document.getElementById('queue');if(!queueState.length){{q.innerHTML='';return;}}q.innerHTML=queueState.map((x,i)=>`<div class="queue-item">${{i+1}}. <b>${{escapeHtml(x.name)}}</b> — ${{escapeHtml(x.status)}}</div>`).join('');}}
function setQueueStatus(i,status){{if(queueState[i]){{queueState[i].status=status;renderQueue();}}}}
function cancelledError(){{const e=new Error('Cancelled');e.cancelled=true;return e;}}
async function waitWhilePaused(){{while(uploadControl.paused&&!uploadControl.cancelled)await new Promise(r=>setTimeout(r,150));if(uploadControl.cancelled)throw cancelledError();}}
function newUploadId(){{return(globalThis.crypto&&crypto.randomUUID)?crypto.randomUUID():('ds_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,12));}}
async function cancelPartial(name,uploadId){{for(let i=0;i<3;i++){{try{{const r=await fetch('/api/cancel-upload',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{name,upload_id:uploadId}})}});if(r.ok)return;}}catch(e){{}}await new Promise(r=>setTimeout(r,120));}}}}
async function uploadStatus(f,uploadId){{const r=await fetch('/api/upload-status?upload_id='+encodeURIComponent(uploadId)+'&name='+encodeURIComponent(f.name)+'&total='+f.size,{{cache:'no-store'}});if(!r.ok)throw new Error(await r.text()||('Status error '+r.status));return r.json();}}
async function stableCheckpoint(f,uploadId,fallback){{let last=-1,same=0,best=fallback;for(let i=0;i<20;i++){{try{{const s=await uploadStatus(f,uploadId),n=Number(s.received||0);if(n>=0&&n<=f.size)best=n;if(n===last)same++;else same=0;last=n;if(s.complete||same>=1)return s;}}catch(e){{}}await new Promise(r=>setTimeout(r,100));}}return{{received:best,complete:false,name:f.name}};}}
function fastUploadRequest(f,off,uploadId,onProgress){{return new Promise((resolve,reject)=>{{const xhr=new XMLHttpRequest(),url='/upload?name='+encodeURIComponent(f.name)+'&offset='+off+'&total='+f.size;xhr.open('PUT',url,true);xhr.setRequestHeader('Content-Type','application/octet-stream');xhr.setRequestHeader('X-DeckyShare-Upload-ID',uploadId);xhr.setRequestHeader('X-DeckyShare-Fast','1');xhr.upload.onprogress=e=>onProgress(Math.min(f.size,off+Number(e.loaded||0)));xhr.onload=()=>{{uploadControl.controller=null;let data={{}};try{{data=JSON.parse(xhr.responseText||'{{}}');}}catch(e){{}}resolve({{status:xhr.status,ok:xhr.status>=200&&xhr.status<300,data,text:xhr.responseText||''}});}};xhr.onerror=()=>{{uploadControl.controller=null;reject(new Error('Connection interrupted'));}};xhr.onabort=()=>{{uploadControl.controller=null;const e=new Error('Upload paused');e.name='AbortError';reject(e);}};uploadControl.controller=xhr;xhr.send(f.slice(off));}});}}
async function uploadOneFast(f,onProgress,onRetry){{const uploadId=newUploadId();let off=0,lastName=f.name,retries=0,first=true;document.getElementById('diag').textContent='Fast mode • native continuous stream • resumable Deck checkpoint';while(first||off<f.size){{first=false;await waitWhilePaused();try{{const r=await fastUploadRequest(f,off,uploadId,onProgress);if(uploadControl.cancelled){{await cancelPartial(f.name,uploadId);throw cancelledError();}}const j=r.data||{{}};if(r.status===409){{off=Number(j.received||0);onProgress(off);onRetry('Resuming from Deck checkpoint '+fmt(off));continue;}}if(!r.ok)throw new Error(j.error||r.text||('Upload error '+r.status));off=Number(j.received||0);lastName=j.name||lastName;retries=0;onProgress(off);if(j.complete)break;}}catch(e){{uploadControl.controller=null;if(uploadControl.cancelled){{await cancelPartial(f.name,uploadId);throw cancelledError();}}const checkpoint=await stableCheckpoint(f,uploadId,off);off=Number(checkpoint.received||0);onProgress(off);if(checkpoint.complete){{lastName=checkpoint.name||lastName;break;}}if(uploadControl.paused){{onRetry('Paused at Deck checkpoint '+fmt(off));await waitWhilePaused();onRetry('Resuming from '+fmt(off));continue;}}retries++;if(retries>5)throw e;onRetry('Connection interrupted — resuming '+fmt(off)+' ('+retries+'/5)');await new Promise(r=>setTimeout(r,500*retries));}}}}return lastName;}}
async function uploadOneReliable(f,onProgress,onRetry){{const uploadId=newUploadId();let chunk=4*1024*1024,off=0,lastName=f.name,retries=0,first=true;document.getElementById('diag').textContent='Reliable compatibility mode • verified 4 MB chunks';while(first||off<f.size){{first=false;try{{await waitWhilePaused();const current=await prepareUploadChunk(f,off,chunk),controller=new AbortController();uploadControl.controller=controller;const r=await fetch('/upload?name='+encodeURIComponent(f.name)+'&offset='+off+'&total='+f.size,{{method:'PUT',headers:{{'Content-Type':'application/octet-stream','X-DeckyShare-CRC32':current.sum,'X-DeckyShare-Upload-ID':uploadId}},body:current.blob,signal:controller.signal}});uploadControl.controller=null;if(uploadControl.cancelled){{await cancelPartial(f.name,uploadId);throw cancelledError();}}const j=await r.json();if(r.status===409){{off=Number(j.received||0);onProgress(off);continue;}}if(!r.ok)throw new Error(j.error||('Upload error '+r.status));off=Number(j.received||0);lastName=j.name||lastName;retries=0;onProgress(off);if(j.complete)break;}}catch(e){{uploadControl.controller=null;if(uploadControl.cancelled){{await cancelPartial(f.name,uploadId);throw cancelledError();}}if(uploadControl.paused){{await waitWhilePaused();continue;}}retries++;if(retries>3)throw e;onRetry('Reliable retry '+retries+'/3');await new Promise(r=>setTimeout(r,600*retries));}}}}return lastName;}}
async function uploadOne(f,onProgress,onRetry){{if(typeof XMLHttpRequest==='undefined')return uploadOneReliable(f,onProgress,onRetry);return uploadOneFast(f,onProgress,onRetry);}}
document.getElementById('download').addEventListener('click',async(e)=>{{
  if(!e.currentTarget.href)return;
  await requestTransferWakeLock();
  setAwakeText('Download started. Keep this page open until your browser reports completion.');
}});

document.getElementById('pause').onclick=()=>{{if(!uploadControl.running)return;uploadControl.paused=!uploadControl.paused;if(uploadControl.paused&&uploadControl.controller)uploadControl.controller.abort();document.getElementById('pause').textContent=uploadControl.paused?'Resume':'Pause';document.getElementById('uptext').textContent=uploadControl.paused?'Pausing at Deck checkpoint…':'Resuming…';}};
document.getElementById('cancel').onclick=()=>{{if(!uploadControl.running)return;uploadControl.cancelled=true;uploadControl.paused=false;if(uploadControl.controller)uploadControl.controller.abort();document.getElementById('pause').textContent='Pause';document.getElementById('uptext').textContent='Cancelling now…';}};
document.getElementById('upload').onclick=async()=>{{const input=document.getElementById('file'),files=Array.from(input.files||[]),u=document.getElementById('uptext'),b=document.getElementById('upbar'),btn=document.getElementById('upload'),pause=document.getElementById('pause'),cancel=document.getElementById('cancel');if(!files.length||uploadControl.running)return;const total=files.reduce((n,f)=>n+f.size,0);let finished=0,current=-1;queueState=files.map(f=>({{name:f.name,status:'Waiting'}}));renderQueue();uploadControl={{running:true,paused:false,cancelled:false,controller:null}};await requestTransferWakeLock();btn.disabled=true;pause.disabled=false;cancel.disabled=false;try{{for(let i=0;i<files.length;i++){{current=i;if(uploadControl.cancelled)throw cancelledError();const f=files[i],label=()=>`${{i+1}}/${{files.length}} • ${{f.name}}`;setQueueStatus(i,'Uploading • Fast mode');await uploadOne(f,done=>{{const overall=total?((finished+done)*100/total):100;u.textContent=label()+' • '+overall.toFixed(1)+'% overall';b.style.width=Math.min(100,overall)+'%';}},s=>{{u.textContent=label()+' • '+s;}});finished+=f.size;setQueueStatus(i,'Done');}}u.textContent=`Completed ${{files.length}} file${{files.length===1?'':'s'}}`;b.style.width='100%';setTimeout(()=>{{u.textContent='';b.style.width='0%';input.value='';queueState=[];renderQueue();}},1800);}}catch(e){{if(e.cancelled){{if(current>=0)setQueueStatus(current,'Cancelled');for(let i=current+1;i<queueState.length;i++)setQueueStatus(i,'Skipped');u.textContent='Transfer queue cancelled';}}else{{if(current>=0)setQueueStatus(current,'Failed');u.textContent='Upload failed after retries: '+e.message;}}}}finally{{uploadControl.controller=null;uploadControl.running=false;uploadControl.paused=false;await releaseTransferWakeLock();btn.disabled=false;pause.disabled=true;cancel.disabled=true;pause.textContent='Pause';}}}};
refresh();setInterval(refresh,700);
</script></body></html>'''
